#!/usr/bin/env python3
"""Stop the 5-second tick from tearing down and rebuilding the task list.

update_timer_cb calls update_task_widgets() every 5 ticks unconditionally, and
update_task_widgets() ends in update_task_list(), which does lv_obj_clean() on
the whole container and recreates every row.  That resets the scroll position
and destroys the row under the user's finger mid-gesture.

task_watch_timer_cb already gates on the file mtime, so the periodic full
rebuild is pure damage.  Split the cheap counter refresh (labels only) from the
expensive list rebuild, and let the tick call only the counters.
"""
import io
import sys

PATH = "study_terminal_main.c"

with io.open(PATH, encoding="utf-8") as f:
    src = f.read()

orig = src

# 1. Split update_task_widgets: keep the label refresh, gate the list rebuild.
old_fn = """#ifndef _WIN32
  update_task_list();
#endif
}
"""
new_fn = """#ifndef _WIN32
  /* The row rebuild is deliberately NOT done here.  update_task_widgets() sits
   * on the 1-second UI tick, and rebuilding the rows means lv_obj_clean() on
   * the container: the scroll position snaps back to the top and the row under
   * the user's finger is deleted mid-gesture, so the tap never lands.  Rows are
   * refreshed by task_watch_timer_cb instead, which fires only when the task
   * file actually changed.
   */

  if (g_task_reload_pending || task_file_mtime() != g_task_file_mtime)
    {
      update_task_list();
    }
#endif
}
"""
n = src.count(old_fn)
if n != 1:
    sys.exit("ABORT: %d occurrences (want 1) of update_task_widgets tail" % n)
src = src.replace(old_fn, new_fn)

# 2. task_watch_timer_cb must force the rebuild, not re-enter the gate.
old_watch = """  if (g_task_reload_pending || task_file_mtime() != g_task_file_mtime)
    {
      update_task_widgets();
    }
}"""
new_watch = """  if (g_task_reload_pending || task_file_mtime() != g_task_file_mtime)
    {
      update_task_widgets();
      update_task_list();
    }
}"""
n = src.count(old_watch)
if n != 1:
    sys.exit("ABORT: %d occurrences (want 1) of task_watch_timer_cb body" % n)
src = src.replace(old_watch, new_watch)

if src == orig:
    sys.exit("ABORT: nothing changed")

with io.open(PATH, "w", encoding="utf-8", newline="") as f:
    f.write(src)

print("OK: task list rebuild gated on file mtime")

