#!/usr/bin/env python3
"""Replace the hard-coded display values with live data.

Three places show numbers the device never computed:

  * home page "2/3"          -- a fixed progress ratio, never updated
  * home page focus subject  -- "阅读 ai_agent 架构" baked into the layout
  * home page "正常"          -- a health lamp that is green no matter what
  * tasks page third card    -- "提醒 / 可用 / 主动提醒已验证", pure decoration
                                (its out-param was literally named `unused`)

A user notices a fabricated number faster than any missing feature, so these
get wired to the task file and the system state that already back the rest of
the page.
"""
import io
import sys

PATH = "study_terminal_main.c"

with io.open(PATH, encoding="utf-8") as f:
    src = f.read()


def sub(old, new, want=1, label=""):
    global src
    n = src.count(old)
    if n != want:
        sys.exit("ABORT: %d occurrences (want %d) of %s" % (n, want, label or old[:60]))
    src = src.replace(old, new)


# --- 1. New struct members for the widgets that must now update ------------
sub(
    """  lv_obj_t *home_task_count;
""",
    """  lv_obj_t *home_task_count;
  lv_obj_t *home_task_ratio;
  lv_obj_t *home_focus_subject;
  lv_obj_t *home_health;
""",
    label="struct: home widgets",
)

