#!/usr/bin/env python3
"""Real weather + honest clock state on the standby face.

Two problems this fixes.

Weather was fabricated: update_standby_widgets() picked between "晴转多云 26C"
and "夜间晴朗 21C" purely on the hour.  The UI process cannot fetch it itself --
CONFIG_NETUTILS_WEBCLIENT is unset, so there is no HTTP client linked in, and
blocking the LVGL thread on a socket would stall the panel anyway.  ai_agent
does have the full TLS/HTTP stack, so it publishes /data/ai_agent/WEATHER.json
and the UI just reads the file, mirroring how STUDY_TASKS.md is already shared
between the two processes.

The clock lied differently: this board has no battery-backed RTC, so before
ntpc completes its first sync time() returns something near the epoch.  Showing
"00:07" then is worse than admitting the clock is not set yet.
"""
import io
import sys

PATH = "study_terminal_main.c"

with io.open(PATH, encoding="utf-8") as f:
    src = f.read()


def sub(old, new, want=1, label=""):
    global src
    n = src.count(old)
    if n != want:
        sys.exit("ABORT: %d occurrences (want %d) of %s" % (n, want, label or old[:60]))
    src = src.replace(old, new)


# --- 1. paths -------------------------------------------------------------
sub(
    """#  define VOLUME_FILE "/data/ai_agent/STUDY_VOLUME.json\"""",
    """#  define VOLUME_FILE "/data/ai_agent/STUDY_VOLUME.json"
#  define WEATHER_FILE "/data/ai_agent/WEATHER.json\"""",
    label="define WEATHER_FILE",
)

# --- 2. clock-valid helper + weather reader ------------------------------
sub(
    """static void update_standby_widgets(void)
{""",
    """/* A wall clock this far past the epoch has been set by something real (ntpc,
 * or a warm reboot that kept RAM).  Anything below it means the clock has not
 * been synced yet: this board has no battery-backed RTC, so a cold boot starts
 * at 0 and every displayed timestamp would be fiction.
 *
 * 2020-01-01 UTC.  Comfortably after any plausible build date, comfortably
 * before any real "now".
 */

#define CLOCK_SYNCED_EPOCH 1577836800

static bool clock_is_synced(time_t wall_time)
{
  return wall_time >= (time_t)CLOCK_SYNCED_EPOCH;
}

#ifndef _WIN32

/* Pull one string field out of the weather file ai_agent publishes.
 *
 * The file is small and flat, so a bounded scan for "\\"key\\"" followed by the
 * next quoted token is enough -- linking a JSON parser into the UI for four
 * fields is not worth the footprint.  Returns false on any malformed input,
 * which the caller renders as "天气未配置" rather than a partial reading.
 */

static bool weather_field(const char *key, char *out, size_t out_size)
{
  FILE *file;
  char buffer[512];
  size_t got;
  char pattern[32];
  char *cursor;
  char *end;

  file = fopen(WEATHER_FILE, "r");
  if (file == NULL)
    {
      return false;
    }

  got = fread(buffer, 1, sizeof(buffer) - 1, file);
  fclose(file);
  buffer[got] = '\\0';

  snprintf(pattern, sizeof(pattern), "\\"%s\\"", key);
  cursor = strstr(buffer, pattern);
  if (cursor == NULL)
    {
      return false;
    }

  cursor = strchr(cursor + strlen(pattern), ':');
  if (cursor == NULL)
    {
      return false;
    }

  cursor = strchr(cursor, '"');
  if (cursor == NULL)
    {
      return false;
    }

  cursor++;
  end = strchr(cursor, '"');
  if (end == NULL || (size_t)(end - cursor) >= out_size)
    {
      return false;
    }

  memcpy(out, cursor, (size_t)(end - cursor));
  out[end - cursor] = '\\0';
  return out[0] != '\\0';
}

#endif

static void update_standby_widgets(void)
{""",
    label="clock_is_synced + weather_field",
)

with io.open(PATH, "w", encoding="utf-8", newline="") as f:
    f.write(src)

print("OK: weather reader and clock-sync helper added")

