/* weather_service.c — periodic weather fetch published as a file.
 *
 * Why a file instead of an API the UI calls
 * -----------------------------------------
 * study_terminal is built without CONFIG_NETUTILS_WEBCLIENT, so it has no HTTP
 * client linked in, and it drives LVGL from a single thread -- a blocking
 * socket there stalls the panel.  ai_agent already carries the TLS stack, so it
 * fetches on its own thread and drops the result in WEATHER_FILE.  The UI polls
 * that file on its existing one-second timer, which is the same arrangement
 * STUDY_TASKS.md already uses between these two processes.
 *
 * Configuration lives in the shared config store, so a key can be changed over
 * the console without reflashing:
 *
 *   weather.key          provider API key; empty disables the service
 *   weather.city         AMap adcode, e.g. 110101; empty means "auto"
 *   weather.refresh_sec  poll interval, default 1800, floor 300
 */

#include "agent_compat.h"
#include "infra/vela_tls.h"
#include "cJSON.h"

#include <errno.h>
#include <fcntl.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "config_store.h"
#include "weather_service.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define TAG "weather"

#define WEATHER_HOST "restapi.amap.com"
#define WEATHER_PORT "443"
#define WEATHER_RESP_SIZE 4096

#define WEATHER_FILE AGENT_DATA_DIR "/WEATHER.json"
#define WEATHER_TEMP_FILE AGENT_DATA_DIR "/WEATHER.json.tmp"

/* AMap's free tier allows a generous but not unlimited call budget, and the
 * weather it returns only changes on the order of tens of minutes.  Half an
 * hour keeps the reading fresh without burning quota; the floor stops a bad
 * config value from turning this into a request loop.
 */

#define WEATHER_REFRESH_DEFAULT_SEC 1800
#define WEATHER_REFRESH_MIN_SEC 300

/* A failed fetch retries sooner than the normal cadence -- the usual cause is
 * WiFi still associating at boot, which resolves in seconds.
 */

#define WEATHER_RETRY_SEC 60

/****************************************************************************
 * Private Data
 ****************************************************************************/

static pthread_t g_weather_thread;
static bool g_weather_running;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* Write the fields the UI reads, atomically.
 *
 * The UI may poll at any moment, so the file is built under a temp name and
 * renamed into place: a reader either sees the previous complete reading or the
 * new complete one, never a half-written object.
 */

static int weather_publish(const char *text, const char *temp,
                           const char *city, const char *humidity)
{
  FILE *file;
  time_t now = time(NULL);

  file = fopen(WEATHER_TEMP_FILE, "w");
  if (file == NULL)
    {
      syslog(LOG_ERR, "[%s] cannot write %s: %d\n", TAG,
             WEATHER_TEMP_FILE, errno);
      return ERROR;
    }

  fprintf(file,
          "{\n"
          "  \"text\": \"%s\",\n"
          "  \"temp\": \"%s\",\n"
          "  \"city\": \"%s\",\n"
          "  \"humidity\": \"%s\",\n"
          "  \"updated\": %lld\n"
          "}\n",
          text, temp, city, humidity, (long long)now);

  if (fclose(file) != 0)
    {
      syslog(LOG_ERR, "[%s] close failed: %d\n", TAG, errno);
      return ERROR;
    }

  if (rename(WEATHER_TEMP_FILE, WEATHER_FILE) != 0)
    {
      syslog(LOG_ERR, "[%s] rename failed: %d\n", TAG, errno);
      unlink(WEATHER_TEMP_FILE);
      return ERROR;
    }

  return OK;
}

/* Pull the live-weather record out of an AMap weatherInfo response.
 *
 * Shape (only the fields used here):
 *   {"status":"1","lives":[{"city":"...","weather":"晴","temperature":"26",
 *                           "humidity":"48"}]}
 *
 * status "0" means AMap rejected the request -- bad key, quota, unknown adcode
 * -- and carries the reason in "info", which is worth logging because it is the
 * difference between a misconfiguration and a network problem.
 */

static int weather_parse_and_publish(const char *raw)
{
  cJSON *root;
  cJSON *status;
  cJSON *lives;
  cJSON *entry;
  cJSON *weather;
  cJSON *temperature;
  cJSON *city;
  cJSON *humidity;
  int ret = ERROR;

  root = cJSON_Parse(raw);
  if (root == NULL)
    {
      syslog(LOG_ERR, "[%s] response was not JSON\n", TAG);
      return ERROR;
    }

  status = cJSON_GetObjectItem(root, "status");
  if (status != NULL && cJSON_IsString(status) &&
      strcmp(status->valuestring, "1") != 0)
    {
      cJSON *info = cJSON_GetObjectItem(root, "info");

      syslog(LOG_ERR, "[%s] provider rejected request: %s\n", TAG,
             (info != NULL && cJSON_IsString(info)) ?
             info->valuestring : "unknown");
      goto done;
    }

  lives = cJSON_GetObjectItem(root, "lives");
  if (lives == NULL || !cJSON_IsArray(lives))
    {
      syslog(LOG_ERR, "[%s] no lives array in response\n", TAG);
      goto done;
    }

  entry = cJSON_GetArrayItem(lives, 0);
  if (entry == NULL)
    {
      syslog(LOG_ERR, "[%s] lives array was empty\n", TAG);
      goto done;
    }

  weather = cJSON_GetObjectItem(entry, "weather");
  temperature = cJSON_GetObjectItem(entry, "temperature");
  city = cJSON_GetObjectItem(entry, "city");
  humidity = cJSON_GetObjectItem(entry, "humidity");

  if (weather == NULL || !cJSON_IsString(weather) ||
      temperature == NULL || !cJSON_IsString(temperature))
    {
      syslog(LOG_ERR, "[%s] record missing weather/temperature\n", TAG);
      goto done;
    }

  ret = weather_publish(weather->valuestring, temperature->valuestring,
                        (city != NULL && cJSON_IsString(city)) ?
                        city->valuestring : "",
                        (humidity != NULL && cJSON_IsString(humidity)) ?
                        humidity->valuestring : "");

  if (ret == OK)
    {
      syslog(LOG_INFO, "[%s] %s %s°C %s\n", TAG, weather->valuestring,
             temperature->valuestring,
             (city != NULL && cJSON_IsString(city)) ? city->valuestring : "");
    }

done:
  cJSON_Delete(root);
  return ret;
}

/* One fetch cycle.  Returns OK only when a fresh reading reached the file. */

static int weather_fetch_once(void)
{
  char key[80];
  char city[32];
  char path[192];
  char *response;
  int status;
  int ret;

  if (claw_config_get("weather.key", key, sizeof(key)) != OK ||
      key[0] == '\0')
    {
      return ERROR;
    }

  if (claw_config_get("weather.city", city, sizeof(city)) != OK)
    {
      city[0] = '\0';
    }

  /* extensions=base asks for the current reading rather than the multi-day
   * forecast, which is all the standby face shows.
   */

  if (city[0] != '\0')
    {
      snprintf(path, sizeof(path),
               "/v3/weather/weatherInfo?key=%s&city=%s&extensions=base",
               key, city);
    }
  else
    {
      /* No adcode configured: AMap resolves the caller's location from the
       * request IP.  Coarse, but better than showing nothing.
       */

      snprintf(path, sizeof(path),
               "/v3/weather/weatherInfo?key=%s&extensions=base", key);
    }

  /* 4 KiB off the heap rather than the stack: this runs on a worker thread
   * with a modest stack, and the response is comfortably the largest thing in
   * this function.
   */

  response = malloc(WEATHER_RESP_SIZE);
  if (response == NULL)
    {
      syslog(LOG_ERR, "[%s] out of memory for response buffer\n", TAG);
      return ERROR;
    }

  status = vela_https_get(WEATHER_HOST, WEATHER_PORT, path,
                          response, WEATHER_RESP_SIZE);
  if (status < 200 || status >= 300)
    {
      syslog(LOG_WARNING, "[%s] HTTP %d\n", TAG, status);
      free(response);
      return ERROR;
    }

  ret = weather_parse_and_publish(response);
  free(response);
  return ret;
}

static int weather_refresh_interval(void)
{
  char value[16];
  int seconds;

  if (claw_config_get("weather.refresh_sec", value, sizeof(value)) != OK)
    {
      return WEATHER_REFRESH_DEFAULT_SEC;
    }

  seconds = atoi(value);
  if (seconds < WEATHER_REFRESH_MIN_SEC)
    {
      return WEATHER_REFRESH_DEFAULT_SEC;
    }

  return seconds;
}

static void *weather_worker(void *arg)
{
  bool announced_disabled = false;

  (void)arg;

  while (g_weather_running)
    {
      char key[80];

      /* Re-read the key every cycle so configuring it over the console takes
       * effect without restarting the agent.
       */

      if (claw_config_get("weather.key", key, sizeof(key)) != OK ||
          key[0] == '\0')
        {
          if (!announced_disabled)
            {
              syslog(LOG_INFO,
                     "[%s] no weather.key configured, service idle\n", TAG);
              announced_disabled = true;
            }

          sleep(WEATHER_RETRY_SEC);
          continue;
        }

      announced_disabled = false;

      if (weather_fetch_once() == OK)
        {
          sleep((unsigned int)weather_refresh_interval());
        }
      else
        {
          /* Most early failures are the network still coming up, so try again
           * shortly rather than waiting out a full refresh period.
           */

          sleep(WEATHER_RETRY_SEC);
        }
    }

  return NULL;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int weather_service_init(void)
{
  pthread_attr_t attr;
  int ret;

  if (g_weather_running)
    {
      return OK;
    }

  g_weather_running = true;

  pthread_attr_init(&attr);

  /* Enough for the TLS handshake plus a 4 KiB response; the buffer itself is
   * heap-allocated so this only has to cover mbedTLS's own frames.
   */

  pthread_attr_setstacksize(&attr, 8192);

  ret = pthread_create(&g_weather_thread, &attr, weather_worker, NULL);
  pthread_attr_destroy(&attr);

  if (ret != 0)
    {
      syslog(LOG_ERR, "[%s] cannot start worker: %d\n", TAG, ret);
      g_weather_running = false;
      return ERROR;
    }

  pthread_detach(g_weather_thread);
  syslog(LOG_INFO, "[%s] service started\n", TAG);
  return OK;
}

void weather_service_stop(void)
{
  g_weather_running = false;
}

